-- 价格修正：把 price_ref 换成「最低配版本」的报价
-- 由 tools/fix_variants.py 生成，可重复执行（幂等）
--
-- 定位键用 specs->>'source_id'（ZOL 商品号），因为 products.json 里没有数据库自增 id。
-- 执行：psql -U postgres -d digital_guide -f db/fix_prices.sql

UPDATE biz.product SET price_ref = 15999, title = '苹果iPhone Duo（256GB）', price_source = 'zol_base_variant' WHERE specs->>'source_id' = '2177484';
UPDATE biz.product SET specs = jsonb_set(specs, '{metrics,rom}', to_jsonb(256::int)) WHERE specs->>'source_id' = '2177484';
